+// Rebuild a cart from a shareable ?items= link: look up each product, ignore
+// unknown ids and clamp quantities to stock (max 5 per line, like the cart forms).
+function cartFromItemsParam(raw) {
+  const cart = [];
+  for (const part of String(raw).split(',')) {
+    const m = /^([A-Za-z0-9-]+):(\d{1,2})$/.exec(part.trim());
+    if (!m) continue;
+    const p = bySku[m[1].toUpperCase()] || bySlug[m[1].toLowerCase()];
+    if (!p || p.stock === 0) continue;
+    const qty = Math.max(1, Math.min(5, p.stock, parseInt(m[2], 10)));
+    const line = cart.find((l) => l.sku === p.sku);
+    if (line) line.qty = Math.min(5, p.stock, line.qty + qty);
+    else cart.push({ sku: p.sku, option: '', qty });
+  }
+  return cart;
